from pathlib import Path
import json,hashlib,shutil
root=Path(__file__).resolve().parents[1];web=root/'docs/simulator/heltec';(web/'wasm').mkdir(parents=True,exist_ok=True)
for name in ('core.mjs','core.wasm'):shutil.copy2(root/'build/heltec/wasm'/name,web/'wasm'/name)
result=json.loads((root/'build/heltec/WASM-TEST-RESULT.json').read_text());assert result['result']=='PASS'
shared=[*sorted((root/'firmware/core').glob('*.h')),*sorted((root/'firmware/ui').glob('*.h')),*sorted((root/'firmware/display').glob('*.h')),root/'simulator/src/Simulator.cpp',root/'simulator/src/FirmwareAdapter.h',root/'simulator/web/Bridge.cpp']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
manifest={'version':'0.2.0-heltec-dev2','status':'PREVIEW','input':'raw PRG levels; gestures resolved by shared C++ PrgInput','format':'Shared C++ simulator compiled to WebAssembly','framebuffer_bytes':1024,'display':[128,64,1],'device_access':False,'hardware_tests':'UNTESTED','physical_revision':'UNKNOWN','bootloader_compatibility':'UNKNOWN','files':{name:sha(web/'wasm'/name) for name in ('core.mjs','core.wasm')},'shared_sources':{str(p.relative_to(root)):sha(p) for p in shared},'native_wasm_tests':result}
(web/'BUILD-MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n');(web/'TEST-RESULT.json').write_text(json.dumps(result,indent=2)+'\n')
(web/'TEST-REPORT.md').write_text(f'''# Heltec Browser-Vorschau – Testbericht\n\nStatus: VORSCHAU · 0.2.0-heltec-dev2 · 22. November 2026.\n\nNative und WebAssembly verwenden denselben C++-Simulatoradapter, Menücode, PRG-Automaten, Telemetrieansichten und Framebuffer. PASS: {result['native_wasm_comparisons']} Vergleiche von jeweils 1024 Pixelbytes und elf Zustandswerten, alle Menüs, Events, Vorlagen und Sperrzustände. Fester WASM-Heap: 16 MiB.\n\nDie rohe Browser-Eingabe wird zusätzlich mit dem tatsächlichen WASM-Modell geprüft: Maus, Leertaste, Autorepeat, Fokusverlust, Pointer-Cancel, gleichzeitige Eingabegeräte, Sperre/RX und Reset. Der Browser enthält keine eigene Gesten- oder Menüimplementierung. Die Original-Wio-WASM und Wio-Downloads bleiben erhalten.\n\nHardware: UNTESTED. R2/R8, tatsächlicher Bootloader und vorhandenes Speicherlayout: UNKNOWN. Keine Geräteports, kein Flash, kein Erase. RX-Pegel und Repeater sind Demodaten. Eine lokale TX-Annahme ist kein Zustellungs-ACK.\n\nSiehe `UI-TEST-RESULT.json` für die automatisierten Browser-Eingabetests sowie `../../HELTEC-TEST-REPORT.md` für Mac/Firmware.\n''')
